/**
 * Catalog schema — the machine-readable index of the curated asset library
 * (`assets/catalog.json`, generated by `scripts/assets/build.ts`).
 *
 * Conventions match the World IR: metres, Y up, every model normalised so
 * its base rests on y = 0 and it is centred on X/Z. File paths are relative
 * to {@link Catalog.base} (served under `/assets/lib/` with immutable cache
 * headers, so every file name carries a content hash).
 */
import '@aether/core';
import { z } from 'zod';

/** Asset ids share the entity-id slug syntax (`sofa`, `tree-oak`, `user-1a2b3c4d5e6f`). */
export const AssetId = z.string().regex(/^[a-z0-9][a-z0-9_-]{0,63}$/, 'asset ids are lowercase slugs');
export type AssetId = z.infer<typeof AssetId>;

/** Browse categories (also the top-level grouping in prompts and the asset browser). */
export const AssetCategory = z.enum([
  'furniture', 'kitchen', 'bathroom', 'decor', 'lighting', 'plants', 'nature', 'rocks', 'building', 'street',
  'vehicles', 'characters', 'animals', 'food', 'tools', 'props', 'sky', 'materials',
]);
export type AssetCategory = z.infer<typeof AssetCategory>;

export const AssetStyle = z.enum(['low-poly', 'realistic', 'stylised']);
export type AssetStyle = z.infer<typeof AssetStyle>;

/** Where an asset naturally goes (drives drag-and-drop snapping and the planner). */
export const AssetPlacement = z.enum(['floor', 'wall', 'ceiling', 'surface']);
export type AssetPlacement = z.infer<typeof AssetPlacement>;

/**
 * Licences the library accepts. Third-party assets must be CC0-1.0 or
 * CC-BY-4.0; "MIT" marks first-party content (procedural generators made
 * with the asset forge, shipped under the project licence). Anything else
 * (NC, ND, editorial-only, unclear) is never shipped.
 */
export const AssetLicence = z.enum(['CC0-1.0', 'CC-BY-4.0', 'MIT']);
export type AssetLicence = z.infer<typeof AssetLicence>;

/** Library file path relative to the catalog base: `m/sofa.0123abcd.glb`. */
export const LibraryPath = z.string().regex(/^[a-z]\/[a-z0-9_-]{1,64}(\.lod[12]|\.albedo|\.orm|\.normal)?\.[0-9a-f]{8}\.(glb|hdr|webp|jpg)$/, 'library paths are content-hashed');

/**
 * Physics collider recorded by the build script, in the asset's normalised
 * local space. `hull` stores support points in centimetres (x, y, z
 * flattened); the physics engine computes the convex hull at load time.
 */
export const CatalogCollider = z.discriminatedUnion('type', [
  z.object({ type: z.literal('box') }),
  z.object({ type: z.literal('capsule') }),
  z.object({ type: z.literal('hull'), points: z.array(z.number().int().min(-100_000).max(100_000)).min(12).max(26 * 3) }),
]);
export type CatalogCollider = z.infer<typeof CatalogCollider>;

/** A lower level of detail (same pivot and scale as the main file). */
export const CatalogLod = z.object({ file: LibraryPath, tris: z.number().int().min(1) });
export type CatalogLod = z.infer<typeof CatalogLod>;

/** Animation clips of a rigged or animated model, with the canonical locomotion roles resolved. */
export const CatalogAnims = z.object({
  idle: z.string().max(64).optional(),
  walk: z.string().max(64).optional(),
  run: z.string().max(64).optional(),
  clips: z.array(z.string().max(64)).max(48),
});
export type CatalogAnims = z.infer<typeof CatalogAnims>;

export const CatalogEntry = z.object({
  id: AssetId,
  name: z.string().min(1).max(60),
  /**
   * `model`: a glTF file; `hdri`: an environment map; `generator`: a
   * procedural (parametric) generator; `material`: photographed PBR maps of a
   * surface finish (used by the renderer for `material.finish`).
   */
  kind: z.enum(['model', 'hdri', 'generator', 'material']),
  category: AssetCategory,
  /** Search keywords (lowercase words), including synonyms ("couch" for a sofa). */
  tags: z.array(z.string().min(1).max(32)).max(32),
  style: AssetStyle,
  /** Pack id (see {@link Catalog.packs}). */
  pack: z.string().min(1).max(64),
  /** Individual authors when they differ from the pack author (Poly Haven). */
  authors: z.array(z.string().max(80)).max(8).optional(),
  /** Bounding-box size in metres (width, height, depth). Zero for HDRIs. */
  size: z.tuple([z.number().min(0).max(500), z.number().min(0).max(500), z.number().min(0).max(500)]),
  tris: z.number().int().min(0),
  bytes: z.number().int().min(0),
  /** Main file (LOD 0). Absent for generators. */
  file: LibraryPath.optional(),
  lods: z.array(CatalogLod).max(2).default([]),
  thumb: LibraryPath.optional(),
  collider: CatalogCollider,
  placement: AssetPlacement,
  /**
   * Direction the model's front points. Props face +Z (like the parametric
   * furniture); things that move — characters, animals, vehicles — face −Z,
   * the engine's forward axis, so behaviors walk and drive them head first.
   */
  facing: z.enum(['+z', '-z']).default('+z'),
  anims: CatalogAnims.optional(),
  /** Alternative looks of the same object (other catalog ids), selectable with the shape's `variant`. */
  variants: z.array(AssetId).max(12).optional(),
  /** Generators: the procedural generator id and default params. */
  generator: z.object({ id: z.string().regex(/^[a-z][a-z0-9-]{1,63}$/), params: z.record(z.string(), z.union([z.number(), z.string(), z.boolean()])).default({}) }).optional(),
  /**
   * Materials: the finish they texture and their maps in the renderer's
   * finish format (albedo ratio to the base colour ÷ the finish's albedo
   * scale, ORM with absolute roughness, OpenGL tangent-space normal), plus
   * the real-world size of one tile in metres.
   */
  material: z
    .object({
      finish: z.string().regex(/^[a-z-]{2,32}$/),
      tile: z.number().positive().max(20),
      maps: z.object({ albedo: LibraryPath, orm: LibraryPath, normal: LibraryPath }),
    })
    .optional(),
  /** Provenance: file path inside the source pack. */
  source: z.string().max(200),
});
export type CatalogEntry = z.infer<typeof CatalogEntry>;
export type CatalogEntryInput = z.input<typeof CatalogEntry>;

export const CatalogPack = z.object({
  id: z.string().min(1).max(64),
  title: z.string().max(80),
  author: z.string().max(120),
  licence: AssetLicence,
  licenceUrl: z.string().url(),
  url: z.string().url(),
  version: z.string().max(32),
});
export type CatalogPack = z.infer<typeof CatalogPack>;

export const Catalog = z.object({
  version: z.literal(1),
  /**
   * URL path prefix the library files are served under: `/assets/lib/` on
   * the studio's origin, or e.g. `/html/12345/assets/lib/` for a published
   * game hosted under a sub-path. Path segments only (no `.` / `..`).
   */
  base: z
    .string()
    .max(200)
    .regex(/^\/(?:[A-Za-z0-9._~-]+\/)*$/)
    .refine((b) => b.split('/').every((seg) => seg !== '.' && seg !== '..'), 'no dot segments'),
  packs: z.array(CatalogPack).max(64),
  entries: z.array(CatalogEntry).max(2000),
});
export type Catalog = z.infer<typeof Catalog>;
export type CatalogInput = z.input<typeof Catalog>;
